sys_script.script:
(function validateTimeCard(current) {
    // 1. Prevent negative hours
    var days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    for (var i = 0; i < days.length; i++) {
        var val = parseFloat(current.getValue(days[i]));
        if (!isNaN(val) && val < 0) {
            gs.addErrorMessage('Negative hours are not allowed for ' + days[i] + '.');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. For project work: validate EWT and consistency
    var reportType = current.getValue('report_type');
    if (reportType == 'work') {
        var ewtId = current.getValue('employee_work_time');
        if (!ewtId) {
            gs.addErrorMessage('Employee Work Time is required for project work time cards.');
            current.setAbortAction(true);
            return;
        }

        // Load the EWT record
        var ewt = new GlideRecord('x_2316178_contin_0_ewt');
        if (!ewt.get(ewtId)) {
            gs.addErrorMessage('Referenced Employee Work Time record not found.');
            current.setAbortAction(true);
            return;
        }

        // Validate user matches EWT.employee
        var userId = current.getValue('user');
        var ewtEmployee = ewt.getValue('employee');
        if (userId != ewtEmployee) {
            gs.addErrorMessage('User must match the Employee Work Time employee.');
            current.setAbortAction(true);
            return;
        }

        // Validate EWT's resource_plan's project_task matches the time card's task
        var taskId = current.getValue('task');
        if (taskId) {
            var rpId = ewt.getValue('resource_plan');
            if (rpId) {
                var rp = new GlideRecord('x_2316178_contin_0_res_plan');
                if (rp.get(rpId)) {
                    var rpProjectTask = rp.getValue('project_task');
                    if (rpProjectTask != taskId) {
                        gs.addErrorMessage('Task must match the Employee Work Time Resource Plan project task.');
                        current.setAbortAction(true);
                        return;
                    }
                }
            }
        }
    }
})(current);
